-- Skye Performance Hub — starter seed data
-- Run AFTER schema.sql, once, in the Supabase SQL editor.
--
-- This seeds: departments, the 24 role scorecards, the two Q2/Q4 2026
-- cycles with their default due dates, and a starter staff roster carried
-- over from the earlier prototype (Finance and Thrive Pastoral Care left
-- out, per Claudia's instruction). Only Claudia's own email is set, so she
-- is the first admin and can sign in immediately; every other person's
-- email is left blank until she adds it from the Staff Admin screen --
-- nobody else is invented an institutional email address here.
--
-- IMPORTANT: replace the email below if claudia.pienaar@skyecollege.co.za
-- is not the address she will sign in with.

on conflict (id) do update set name = excluded.name, sort_order = excluded.sort_order;

on conflict (key) do update set title = excluded.title, note = excluded.note, dimensions = excluded.dimensions, standards = excluded.standards, sort_order = excluded.sort_order;

on conflict (id) do update set label = excluded.label, sort_order = excluded.sort_order;

-- Deterministic ids for this seed run only, so manager_id references
-- resolve correctly. Anyone you add later from the app gets whatever id
-- Postgres assigns automatically — these fixed ids are only to make this
-- one-off seed script self-contained.
on conflict (id) do nothing;

