insert into departments (id, name, sort_order) values
  ('preschool', 'Preschool', 0),
  ('prep', 'Prep School', 1),
  ('high', 'High School', 2),
  ('sports', 'Sports', 3),
  ('ops', 'Operations', 4),
  ('exec', 'Executive', 5)
insert into scorecards (key, title, note, dimensions, standards, sort_order) values
  ('executive_head', 'Executive Head', 'Covers the Executive Head, accountable to the Skye Board and ThriveEd Group for whole-school strategy, safeguarding, staffing, finance, governance and reputation, Preschool to Grade 12. Formal sign-off for this role sits with the Skye Board or the ThriveEd Group governance structure, since the Executive Head has no line manager within the school.', '[{"name": "Strategic and academic leadership", "dnm": "Phase plans are not visibly aligned to a whole-school strategy, or whole-school academic outcomes are not reported to the board against benchmark on schedule", "good": "Maintains a whole-school strategy that every phase plan is aligned to, and reports academic outcomes to the board against benchmark on the agreed schedule", "better": "Uses cross-phase data to identify strategic risks before they surface in a single phase, and adjusts whole-school priorities mid-year where the evidence supports it", "best": "Can evidence a multi-year trajectory of improvement in academic outcomes tied to specific whole-school decisions, and the strategy is a reference point the board and ThriveEd Group cite in their own planning"}, {"name": "Safeguarding, PBS and risk oversight", "dnm": "A phase is without an appointed, resourced safeguarding lead, or Tier 1 PBS accreditation is at risk of lapsing without a remediation plan in place", "good": "A safeguarding lead is appointed and resourced in every phase, Tier 1 PBS accreditation is retained, and behaviour data is reviewed across phases on a regular schedule", "better": "Tier 2 and Tier 3 PBS support is resourced ahead of demand rather than reactively, and safeguarding incident closure is tracked and reported to the board within agreed timeframes", "best": "Whole-school safeguarding and PBS practice is cited by external accreditation or regulatory reviewers as a strength, and closure rates and behaviour trends show sustained improvement over multiple terms"}, {"name": "Staff leadership, appointment and succession", "dnm": "Appointment, performance or succession decisions for the Heads of School and Head of Sports are made without a documented process, or leadership vacancies are left unaddressed beyond a reasonable period", "good": "Leads appointment, performance management and succession planning for the Heads of School and Head of Sports, and approves Deputy and Subject Head appointments on the Head of School''s recommendation within agreed timeframes", "better": "Maintains an active succession pipeline for Head of School and Head of Sports roles, so a vacancy does not leave a phase without confirmed leadership", "best": "Staff retention and talent density at leadership level show a sustained upward trend, and the succession pipeline has been tested by at least one internal promotion into a Head of School or Head of Sports role"}, {"name": "Governance and decision escalation", "dnm": "Sanctions above the delegated threshold, suspensions beyond a Head''s authority, permanent exclusions or dismissal decisions are made without documented rationale or without board notification where required", "good": "Sanctions above threshold, permanent exclusions and dismissal decisions are made with documented rationale, the board is notified where required, and boundary disputes between roles in the framework are resolved without unreasonable delay", "better": "Boundary disputes and final-tier parent complaints are resolved in a way that is referenced back to the framework document, reducing repeat escalations of the same type", "best": "The rate of matters requiring Executive Head level escalation is falling year on year, evidencing that delegated authority is working as intended at Head of School level"}, {"name": "Stakeholder relationships and reputational management", "dnm": "Parent trust signals are not measured or reported, or crisis and reputational communications are handled without a documented approach", "good": "Parent trust is measured and reported to the board, and crisis or reputational communication is handled promptly and consistently with the school''s position", "better": "Proactively communicates with families and the board ahead of issues becoming reputational, rather than only responding once they surface", "best": "Parent trust signal shows sustained improvement, and the school''s handling of a genuine crisis or reputational issue is cited internally as a model for how such matters should be managed"}, {"name": "Framework, budget and resource strategy", "dnm": "Strategy and budget recommendations are not brought to the board on schedule, or the role ecosystem framework is not reviewed annually as required", "good": "Brings strategy and budget recommendations to the board on schedule, and reviews and approves the role ecosystem framework annually", "better": "Budget recommendations are evidenced with data on academic, staffing and safeguarding outcomes rather than presented as a standalone financial case", "best": "The framework and budget approach have been adjusted at least once based on a documented lesson from its own review cycle, showing the governance process is genuinely iterative rather than a formality"}]'::jsonb, '["A safeguarding lead is appointed and resourced in every phase, and every safeguarding concern escalated to the Executive Head is actioned within statutory timelines", "Tier 1 PBS accreditation is retained school-wide, with behaviour data reviewed across phases on a regular schedule", "Board reporting on academic outcomes, behaviour, safeguarding, staffing and parent trust is submitted on the agreed schedule", "Student and family information is handled in line with POPIA", "Staff dismissal decisions and sanctions above the delegated threshold are documented, with board notification given where required", "Appointment, performance and succession decisions for the Heads of School and Head of Sports are documented and on file", "The role ecosystem framework is reviewed and approved annually"]'::jsonb, 0),
  ('head_of_preschool', 'Head of Preschool', 'Covers the Head of Preschool, responsible to the Executive Head for the Nest to Grade R (age 3 months to Grade R), including line management of Preschool teachers, assistants, the Stay and Play Coordinator and the Learn to Swim Teacher.', '[{"name": "Phase strategic and academic leadership", "dnm": "The phase plan is not visibly aligned to the whole-school strategy and the 4 Pathways, or children''s developmental progress is not tracked and reported to families", "good": "Leads a phase plan aligned to the whole-school strategy and 4 Pathways, and oversees developmental tracking and reporting to families from the Nest through to Grade R", "better": "Uses developmental tracking data across classes to identify children needing early intervention before a concern is raised by a parent or teacher", "best": "Grade R readiness outcomes show a sustained trend of improvement, and the phase''s early learning approach is one other phases or new staff are directed to as a model"}, {"name": "Staff leadership and performance management", "dnm": "Appraisal sign-off, leave, conduct or performance matters for Preschool staff are not documented, or staff-to-child ratios are breached without an authorised, recorded temporary change", "good": "Line manages all Preschool staff, including appraisal sign-off, leave, conduct and performance, and authorises and records any temporary ratio change", "better": "Identifies and addresses underperformance or conduct concerns among Preschool staff before they require formal escalation", "best": "Staff retention in the phase is sustained at a high level, and the Head can evidence specific coaching that moved a staff member from a lower to a higher appraisal rating"}, {"name": "Safeguarding, PBS and regulatory compliance", "dnm": "Safeguarding concerns are not reported or logged within statutory timelines, or partial care registration, inspection or staff clearance requirements lapse without being flagged", "good": "Acts as phase safeguarding lead, reporting concerns within statutory timelines and maintaining the phase incident log; partial care registration, inspections and staff clearances are current and shared with the Operations Lead", "better": "PBS Tier 2 and Tier 3 escalations from class teachers are resolved with documented outcomes, and behaviour data in the phase is reviewed proactively rather than only when an incident occurs", "best": "The phase''s safeguarding and registration compliance record has no lapses over a sustained period, and its PBS practice is cited as evidence in the school''s Tier 1 accreditation review"}, {"name": "Stakeholder relationships and family communication", "dnm": "Allergy and dietary information does not consistently reach the staff responsible for a child''s food, care and activities, or decisions on sending ill children home vary inconsistently between classes", "good": "Ensures allergy and dietary information reaches everyone responsible for a child, and applies consistent decisions on sending ill children home across all classes, with final say on escalated cases", "better": "Parent complaints within the phase are resolved at first point of contact more often than they are escalated, and settling-in support for new enrolments is proactive rather than reactive", "best": "Parent feedback in the phase shows a sustained positive trend, and the Head is sought out by the Head of Prep School and Grade 1 teachers as the primary source on individual children''s readiness"}, {"name": "Budget and risk management", "dnm": "The phase budget or risk log is not maintained, or is not available on request", "good": "Maintains the phase budget and risk log to a current, accurate standard", "better": "Identifies and flags budget or risk items proactively, ahead of them becoming urgent", "best": "Phase budget management has contributed a documented efficiency or resourcing improvement without compromising ratios or care standards"}, {"name": "School readiness and transition decisions", "dnm": "School readiness or Grade R repeat recommendations are made without consulting class teachers or liaising with the Head of Prep School and Grade 1 teachers", "good": "Makes school readiness and Grade R repeat recommendations jointly with class teachers, in liaison with the Head of Prep School and Grade 1 teachers", "better": "Readiness recommendations are supported by documented developmental tracking evidence specific to the child, not a general impression", "best": "Grade R to Grade 1 transitions show a consistently smooth handover, with no documented case of a readiness recommendation being reversed or disputed after transition"}]'::jsonb, '["Every safeguarding concern is reported within statutory timelines and recorded in the phase incident log", "PBS behaviour incidents are logged on the PBS system accurately and promptly, with restorative practice as the default response", "Partial care registration, inspection requirements and staff clearances are kept current and shared with the Operations Lead", "Staff-to-child ratios are maintained in every class, with any temporary change authorised and documented", "Student and family information, including medical and allergy information, is handled in line with POPIA", "Signed appraisal documentation is on file for every direct report, for every review cycle", "Allergy and dietary information is confirmed as communicated to all staff responsible for a child''s food, care and activities"]'::jsonb, 1),
  ('head_of_prep_school', 'Head of Prep School', 'Covers the Head of Prep School, responsible to the Executive Head for Grade 1 to 7, including line management of the JP Phase Coordinator, Grade Coordinators, the Aftercare Manager, and all Prep teachers, interns and assistants.', '[{"name": "Strategic and academic leadership", "dnm": "The phase plan is not aligned to the whole-school strategy and the 4 Pathways, or Grade 4 to 7 subject standards and common assessments are approved without evidence of moderation", "good": "Leads a phase plan aligned to the whole-school strategy and 4 Pathways, and gives final approval to Grade 4 to 7 subject standards, schemes of work and common assessments proposed by Subject Heads, with moderation evidenced", "better": "Uses reading, numeracy and Grade 4 to 7 subject outcome data to identify trends across grades before they surface as individual concerns, and adjusts the phase plan mid-year where the data supports it", "best": "Can evidence a multi-term trajectory of improvement in reading, numeracy or subject outcomes tied to specific interventions led personally, and the phase''s approach is a reference point for other phases"}, {"name": "Staff leadership and performance management", "dnm": "Line management of Prep teaching staff, including appraisal sign-off, leave, conduct and performance, is not documented, or Subject Head evidence is not incorporated into Grade 4 to 7 staff appraisals", "good": "Line manages all Prep teaching staff, incorporating Subject Head evidence on subject practice in Grade 4 to 7, and manages teacher deployment and the Prep timetable", "better": "Addresses underperformance or conduct concerns among Prep staff before they require formal escalation, and deployment decisions are visibly matched to identified staffing or curriculum needs", "best": "Staff retention in the phase is sustained at a high level, and the Head can evidence specific development that moved a staff member from a lower to a higher appraisal rating"}, {"name": "Student affairs, safeguarding and PBS oversight", "dnm": "Serious offences referred by Grade Coordinators are not investigated or resolved within the Head''s delegated threshold, or PBS Tier 1 fidelity is not maintained across the phase", "good": "Acts as student affairs lead and phase safeguarding lead for Grade 1 to 7, making disciplinary decisions within the delegated threshold and quality assuring Grade Coordinator investigations and sanctions; leads the phase PBS team with Tier 1 fidelity maintained and Tier 2 and Tier 3 decisions documented", "better": "Reviews phase behaviour data on a regular, proactive schedule and can point to a specific adjustment made to Tier 2 or Tier 3 support as a result", "best": "Behaviour ratios and PBS data in the phase show sustained improvement, and quality assurance of Grade Coordinator investigations has not surfaced a repeat procedural gap over multiple terms"}, {"name": "Learning support and individual student planning", "dnm": "Individual Support Plans for Prep students are not signed off, or the Student Support Coordinator''s work on Prep cases is not directed or reviewed", "good": "Directs the Student Support Coordinator''s work on Prep cases for Grade 4 to 7, signs off individual support plans, gives written appraisal input, and supports learning support in Grade 1 to 3 with the JP Phase Coordinator", "better": "Individual support plans are reviewed against progress data at defined points in the term, not only at sign-off", "best": "Learning support outcomes for identified Prep students show a documented, sustained improvement, and the Student Support Coordinator''s appraisal input reflects specific, evidenced casework quality"}, {"name": "Transitions and stakeholder relationships", "dnm": "Grade 3 to 4 or Grade 7 to 8 transition records are handed over incompletely or late, or parent complaints within the phase are not resolved or tracked", "good": "Oversees complete, on-time handover of records for Grade 3 to 4 and Grade 7 to 8 transitions, and manages parent relationships and complaints within the phase to resolution", "better": "Transition handovers include specific developmental or academic notes that visibly inform the receiving teacher''s early planning for the student", "best": "Parent feedback in the phase shows a sustained positive trend, and receiving Heads or teachers cite the quality of transition handovers as a specific strength"}, {"name": "Budget, resourcing and aftercare oversight", "dnm": "The phase budget or risk log is not maintained, or aftercare and holiday care oversight through the Aftercare Manager is not evidenced", "good": "Maintains the phase budget and risk log to a current, accurate standard, and oversees aftercare and the holiday care programme through the Aftercare Manager", "better": "Identifies and flags budget or risk items proactively, ahead of them becoming urgent", "best": "Phase budget management has contributed a documented efficiency or resourcing improvement without compromising staffing or care standards"}]'::jsonb, '["Every safeguarding concern is reported within statutory timelines", "PBS behaviour incidents are logged accurately and promptly, with restorative practice as the default response, and Tier 1 fidelity is maintained across Grade 1 to 7", "Individual Support Plans for Prep students are signed off and on file", "Student and family information is handled in line with POPIA", "Signed appraisal documentation is on file for every direct report, for every review cycle", "Grade 3 to 4 and Grade 7 to 8 transition records are handed over complete and on schedule", "Disciplinary decisions within the delegated threshold are documented; immediate suspensions are reported to the Executive Head without delay"]'::jsonb, 2),
  ('head_of_high_school', 'Head of High School', 'Covers the Head of High School, responsible to the Executive Head for Grade 8 to 12, leading through the Deputy Head Academics and Deputy Head Student Affairs, and holding the HR line for all High School teaching staff and the Student Support Coordinator.', '[{"name": "Strategic and academic leadership, including examination transition", "dnm": "The phase plan is not aligned to the whole-school strategy and the 4 Pathways, or Grade 8 to 12 subject standards are approved without a clear recommendation from the Deputy Head Academics", "good": "Leads a phase plan aligned to whole-school strategy and the 4 Pathways, and gives final approval to Grade 8 to 12 subject standards on the Deputy Head Academics'' recommendation", "better": "Uses examination results data against benchmark, across both IEB and the remaining Cambridge cohort, to identify subject-level trends before they surface as individual concerns", "best": "Can evidence a multi-term trajectory of improvement in examination results tied to specific decisions led personally, and the phase''s approach is a reference point for other phases"}, {"name": "Accountability for the Cambridge to IEB transition", "dnm": "Umalusi or IEB compliance obligations are not evidenced, or transition milestones for the Cambridge to IEB move are missed without an escalation or remediation plan", "good": "Acts as Accountable Head of Centre for IEB and for Cambridge until the final Cambridge cohort completes at the end of 2028, meeting Umalusi and IEB compliance obligations and transition milestones on schedule", "better": "Transition risks specific to running two examination bodies concurrently, such as staff capacity or timetabling conflicts, are identified and mitigated ahead of the milestone they would affect", "best": "The Cambridge to IEB transition in the High School is completed with no compliance finding against Umalusi or IEB, and the approach is referenced by the Executive Head in board reporting on the transition"}, {"name": "Staff leadership and performance management", "dnm": "Performance management of the two Deputies is not documented, or line management of High School teaching staff, including appraisal sign-off, does not incorporate evidence from the Deputies and Subject Heads", "good": "Performance manages both Deputies, and line manages all High School teaching staff, including appraisal sign-off, leave, conduct and performance, with evidence drawn from the Deputies and Subject Heads", "better": "Addresses underperformance or conduct concerns among teaching staff or a Deputy before they require formal escalation", "best": "Staff retention and capability in the High School show a sustained positive trend, and the Head can evidence specific development that moved a Deputy or teacher to a materially stronger appraisal outcome"}, {"name": "Safeguarding, PBS and disciplinary oversight", "dnm": "Behaviour data is not reviewed regularly with the Deputy Head Student Affairs, or disciplinary hearings and sanctions above the Deputy''s threshold are not documented, or immediate suspensions are not reported to the Executive Head without delay", "good": "Is accountable for PBS in the High School, reviewing behaviour data regularly with the Deputy Head Student Affairs, and holds disciplinary hearings and sanctions above the Deputy''s threshold, notifying the Executive Head without delay on any immediate suspension", "better": "Behaviour trend data is used to adjust Tier 2 or Tier 3 support in the High School before it is raised as a concern by the Deputy Head Student Affairs", "best": "Behaviour ratios in the High School show sustained improvement, and disciplinary hearing outcomes have not been overturned or disputed on appeal over a sustained period"}, {"name": "Stakeholder relationships", "dnm": "High School parent complaints are not resolved at the final phase-level tier, or progress monitoring and reporting to families is inconsistent across grades", "good": "Resolves High School parent complaints at the final phase-level tier, and oversees consistent progress monitoring, reporting and communication with families across Grade 8 to 12", "better": "Parent complaints are resolved at first point of contact by Grade Coordinators more often than they are escalated to the Head, evidencing effective delegation", "best": "Parent feedback for the High School shows a sustained positive trend, and the Head is cited by the Executive Head as a source of proactive, not reactive, family communication"}, {"name": "Budget, staffing and succession recommendations", "dnm": "The phase budget, staffing establishment or risk log is not maintained, or Deputy and Subject Head appointment recommendations to the Executive Head are not documented", "good": "Maintains the phase budget, staffing establishment and risk log to a current, accurate standard, and recommends Deputy and Subject Head appointments to the Executive Head with documented rationale", "better": "Staffing establishment decisions are visibly linked to the examination transition timeline, anticipating capacity needs rather than reacting to them", "best": "Phase budget and staffing decisions have contributed a documented efficiency or capability improvement, and at least one Deputy or Subject Head recommendation has resulted in a successful internal appointment"}]'::jsonb, '["Every safeguarding concern is reported within statutory timelines; immediate suspensions are reported to the Executive Head without delay", "PBS behaviour data is reviewed regularly with the Deputy Head Student Affairs, and behaviour incidents are logged accurately and promptly with restorative practice as the default response", "Umalusi and IEB compliance obligations are met, and examination centre obligations for the remaining Cambridge cohort are met until it completes at the end of 2028", "Student and family information is handled in line with POPIA", "Signed appraisal documentation is on file for both Deputies and every direct report, for every review cycle", "Disciplinary hearing outcomes and sanctions above the Deputy''s delegated threshold are documented", "Phase budget, staffing establishment and risk log are maintained current and available on request"]'::jsonb, 3),
  ('deputy_head_academics', 'Deputy Head Academics', 'Covers the Deputy Head Academics, who reports to the Head of High School and leads the Subject Heads and the Academic Coordinator and Examinations Officer, with academic reach into Grade 4 to 7 through the Subject Heads.', '[{"name": "Academic planning and calendar", "dnm": "The High School assessment policy, academic calendar or timetable input is late, internally inconsistent or not communicated to Subject Heads and families", "good": "Academic plan, assessment policy and academic calendar are published on schedule, applied consistently, and timetable and class placement input is submitted to the Head of High School for sign-off on time", "better": "Subject Head proposals for Grade 8 to 12 are reviewed and recommended to the Head of High School with clear rationale, and conflicts between subjects are resolved before they reach families", "best": "The academic plan is proactively adjusted using prior-term outcome data, and Subject Heads report the review process as improving their own subject planning"}, {"name": "Subject Head leadership", "dnm": "Subject Heads'' KRAs are not reviewed, or underperformance in a subject area goes unaddressed", "good": "Each Subject Head''s performance against their subject KRAs is reviewed on schedule, with lesson observation evidence provided to the Head of High School for appraisal", "better": "Subject Heads are coached between formal review points, and moderation or subject outcome concerns are addressed before they affect a full cohort", "best": "Subject Heads across all four subject areas can evidence coherent Grade 4 to 12 vertical alignment, credited by this Deputy''s oversight"}, {"name": "Cambridge to IEB transition oversight", "dnm": "Grade 9 into 10 subject choice advisement or IEB compliance oversight is inconsistent, or Cambridge Grade 11 and 12 cohorts receive materially less academic attention than IEB cohorts", "good": "Grade 9 into 10 IEB subject choice advisement is delivered to all students, and IEB, Umalusi and Cambridge compliance oversight, executed through the Academic Coordinator, shows no gaps", "better": "Transition planning is documented ahead of each academic year, showing how Cambridge cohorts are protected to the end of 2028 while IEB adoption proceeds from Grade 10 down", "best": "The transition plan is used as a reference point by other phases, with no Cambridge candidate disadvantaged and no IEB compliance finding raised"}, {"name": "Academic data analysis and remediation", "dnm": "Students of academic concern are not identified from data, or a remediation programme is not in place", "good": "Academic data is analysed each reporting cycle, students of concern are identified, and a remediation programme is running with behaviour data read alongside academic data as PBS requires", "better": "Remediation impact is tracked against baseline, and academic concerns are cross-referenced with the Student Support Coordinator and Grade Coordinators where relevant", "best": "Remediation programmes show measurable improvement in outcomes for identified students, with the approach adapted where it is not working"}, {"name": "Progress reporting and access arrangements", "dnm": "Reports to families are inaccurate, late, or access arrangement and concession approvals are granted without evidence from the Student Support Coordinator", "good": "Progress reports to families are accurate and timely, and access arrangements and concessions are approved only on Student Support Coordinator evidence", "better": "Families raising academic concerns receive a substantive response within an agreed turnaround, and concession decisions are documented with the evidence relied on", "best": "Reporting quality and concession decision-making are cited as a model by the Head of High School, with no upheld family complaint about report accuracy"}, {"name": "Lesson observation and classroom expectations", "dnm": "The lesson observation programme is not run to schedule, or observation evidence is not provided to the Head of High School", "good": "The lesson observation programme runs on schedule, and observation evidence, including consistency with the PBS classroom expectations framework, is provided to the Head of High School for appraisal", "better": "Observation findings are used to identify subject-wide coaching needs, not only individual teacher concerns", "best": "Classroom expectations are demonstrably consistent across subjects and grades, with observation evidence directly shaping the academic remediation and CPD priorities"}]'::jsonb, '["Every safeguarding concern is escalated immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable, with no exceptions.", "Behaviour incidents observed or reported are recorded on the PBS system accurately and promptly, with restorative practice applied as the default response.", "Student and family academic data, including reports of concern and remediation records, are handled in line with POPIA.", "Access arrangement and concession approvals are documented and retained on file, with the supporting Student Support Coordinator evidence pack attached.", "Signed review documentation is on file for every Subject Head and for the Academic Coordinator and Examinations Officer, for every review cycle.", "IEB, Umalusi and Cambridge compliance oversight shows no missed sign-off or unreviewed compliance item raised by the Academic Coordinator and Examinations Officer.", "The academic calendar, assessment policy and progress reports are issued to families within the published deadlines each cycle.", "Cambridge Grade 11 and 12 cohorts are protected on the agreed timeline to the end of 2028, with no candidate moved onto IEB requirements without formal subject choice advisement."]'::jsonb, 4),
  ('deputy_head_student_affairs', 'Deputy Head Student Affairs', 'Covers the Deputy Head Student Affairs, who reports to the Head of High School, is the Designated Safeguarding Lead for the High School, and leads the Grade Coordinators for Grade 8 to 12 and the Student Support Coordinator''s High School work.', '[{"name": "Safeguarding leadership", "dnm": "Safeguarding concerns are not received and logged promptly, or statutory reports are late or incomplete", "good": "All safeguarding concerns are received, statutory reports are made where required, and the safeguarding record is kept current and accurate", "better": "Safeguarding practice is reviewed proactively with the High School PBS and pastoral teams, rather than only after an incident", "best": "The safeguarding record and reporting practice would withstand external audit without correction, and staff consistently know to escalate to this role"}, {"name": "PBS Tier 1 to 3 leadership", "dnm": "Tier 1 fidelity checks, staff PBS training or behaviour data and ratio reporting are inconsistent or overdue", "good": "Tier 1 fidelity is monitored, Tier 2 and Tier 3 pathways are applied as designed, staff PBS training is delivered, and behaviour data and ratios are reported on schedule", "better": "Behaviour data trends are used to adjust Tier 2 and Tier 3 support before patterns escalate to disciplinary matters", "best": "Behaviour ratios show sustained improvement attributable to this leadership, with the High School PBS team functioning without close direction"}, {"name": "Disciplinary decision-making and QA", "dnm": "Serious disciplinary matters are not investigated to a defensible standard, or Grade Coordinator investigations and below-threshold sanctions are not quality assured", "good": "Serious matters referred by Grade Coordinators are investigated and decided within the delegated threshold, and Grade Coordinator investigations and sanctions are quality assured for procedural fairness", "better": "Disciplinary outcomes are consistent across similar cases, and hearings are prepared with complete evidence packs", "best": "Disciplinary consistency and procedural fairness are cited by the Head of High School as reducing escalation and appeal"}, {"name": "Grade Coordinator leadership", "dnm": "Grade Coordinators'' goals, reviews or conduct concerns are not actioned on the required timeline", "good": "All Grade Coordinators have goals set and reviews completed on schedule, with any conduct concern documented and actioned per policy", "better": "Grade Coordinators are coached proactively on investigation quality and case management between formal review points", "best": "Grade Coordinators operate with reduced need for escalation to this Deputy, evidencing a strong pastoral team"}, {"name": "ISP sign-off and pastoral case oversight", "dnm": "Individual support plans for Grade 8 to 12 are signed off late or without adequate review", "good": "ISPs for Grade 8 to 12 are reviewed and signed off within agreed timelines, and new student onboarding and camps are properly overseen", "better": "ISP sign-off includes cross-checking with academic concerns raised by the Deputy Head Academics or Subject Heads", "best": "ISP quality and onboarding practice are used as the reference standard for pastoral case management in the High School"}, {"name": "Parent escalation and anti-bullying practice", "dnm": "Escalated parent concerns on discipline or pastoral matters are not resolved or communicated in writing", "good": "Parent escalations are handled as the senior point of contact, resolved or clearly communicated, and anti-bullying and anti-abuse procedures are applied consistently", "better": "Recurring bullying or abuse patterns are identified from case data and addressed at a systemic level, not only case by case", "best": "Escalations to the Head of High School are demonstrably reduced, with anti-bullying outcomes tracked and improving"}]'::jsonb, '["As Designated Safeguarding Lead, every safeguarding concern is received and actioned immediately, with statutory reports made in line with the Children''s Act and Sexual Offences Act, and directly to the Executive Head if this role is implicated or unavailable.", "The High School safeguarding record is kept accurate, current and available for audit at all times.", "Behaviour incidents are recorded on the PBS system accurately and within 24 hours, with restorative practice applied as the default response.", "Student and family pastoral, disciplinary and safeguarding information is handled in line with POPIA.", "Individual support plans for Grade 8 to 12 are signed off and on file for every student requiring one.", "Signed review documentation is on file for every Grade Coordinator and for the Student Support Coordinator''s High School work, for every review cycle.", "Grade Coordinator investigations and below-threshold sanctions are quality assured and documented for procedural fairness before being closed.", "Serious disciplinary matters referred for hearing are prepared with a complete, documented evidence pack."]'::jsonb, 5),
  ('academic_coordinator', 'Academic Coordinator', 'Covers the Academic Coordinator and Examinations Officer, who reports to the Deputy Head Academics and holds a procedural role administering assessment and examinations in the High School, with invigilators as direct reports when rostered.', '[{"name": "Examination administration accuracy", "dnm": "Candidate registrations, entries, timetables or secure materials handling contain errors, or portal administration is incomplete", "good": "Candidate registrations, entries, examination timetables and secure materials are administered accurately for both IEB and Cambridge, with the portal kept up to date", "better": "Potential registration or entry errors are identified and corrected before they affect a candidate", "best": "External examination bodies raise no administrative discrepancy against the school for a full examination cycle"}, {"name": "Deadline management", "dnm": "An external deadline for IEB or Cambridge entries, SBA or portfolio submissions, or results processing is missed", "good": "All external deadlines for IEB and Cambridge entries, SBA and portfolio submissions, and results are met", "better": "Deadlines are tracked ahead of time with staff reminded in sufficient time to avoid last-minute submissions", "best": "Zero missed external deadlines across a full academic year, with predictable assessment cycles that Subject Heads can plan against"}, {"name": "Invigilation and exam-day PBS conduct", "dnm": "Invigilation rosters are incomplete or invigilators are not briefed on PBS-consistent responses, or incidents during exams are not logged", "good": "Invigilation rotas are complete, invigilators are briefed on PBS-consistent responses, and examination incidents are logged on the PBS system", "better": "Invigilator briefings are tailored to the specific risks of each examination session", "best": "Examination sessions run without avoidable incident, and invigilator briefing quality is referenced as a standard for other exam venues"}, {"name": "Compliance and audit readiness", "dnm": "Documentation for IEB, Umalusi, Cambridge or ISASA reviews is incomplete or not readily available", "good": "Full IEB, Umalusi and Cambridge compliance is maintained, and the school is audit-ready for ISASA reviews at all times", "better": "Compliance gaps are identified and closed proactively ahead of a scheduled review", "best": "An external audit or review finds no compliance gap requiring correction"}, {"name": "Records, concessions and predicted grades", "dnm": "Academic records on D6, concession or access arrangement submissions, or the predicted grades process contain errors or are submitted late", "good": "Academic records and report logistics on D6 are accurate and current, concession and access arrangement applications are submitted from the Student Support Coordinator''s evidence packs without delay, and predicted grades are processed on schedule", "better": "Records and submissions are checked for consistency across systems before external submission", "best": "Records, concessions and predicted grades processes run with no correction required after external submission"}]'::jsonb, '["Every safeguarding concern is escalated immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable.", "Behaviour incidents during examinations are logged on the PBS system accurately and within 24 hours, with invigilators briefed on PBS-consistent responses as the default.", "Candidate and academic records, including D6 report data and concession evidence, are handled in line with POPIA.", "Zero missed external deadlines for IEB and Cambridge entries, SBA and portfolio submissions, and results, for every examination cycle.", "Secure examination materials are handled per the exam board''s security protocol, with any irregularity documented and reported without delay.", "Concession and access arrangement applications are submitted to IEB, and to Cambridge until the end of 2028, only from a completed Student Support Coordinator evidence pack.", "Examination misconduct is documented and reported to the Deputy Head Academics for decision, never decided unilaterally.", "Audit readiness for IEB, Umalusi, Cambridge and ISASA reviews is maintained continuously, not assembled only when a review is announced."]'::jsonb, 6),
  ('grade_coordinator', 'Grade Coordinator', 'Covers the pastoral and first-line discipline coordinator for one grade, Grade 4 to 12, reporting to the Head of Prep School (Grade 4 to 7) or the Deputy Head Student Affairs (Grade 8 to 12).', '[{"name": "Below-threshold investigation and sanctioning", "dnm": "Investigations are incomplete or undocumented, interviews are not conducted in line with the Code of Conduct, or sanctions are applied inconsistently between students for comparable offences", "good": "Below-threshold offences are investigated and interviewed in line with the Code of Conduct, with evidence recorded and sanctions applied consistently with the Code of Conduct threshold", "better": "Investigation files are complete and ready for escalation without rework, and sanctions reflect a clear, predictable pattern for students and families", "best": "Below-threshold sanctioning is consistent enough across the grade that the Deputy Head Student Affairs or Head of Prep School cites it as the reference standard for other Grade Coordinators"}, {"name": "Escalation judgement", "dnm": "Matters that exceed the below-threshold limit, or safeguarding concerns, are investigated or sanctioned by the Grade Coordinator instead of being referred immediately", "good": "Matters above the threshold, and all safeguarding concerns, are referred immediately to the Deputy Head Student Affairs, Head of Prep School, or phase safeguarding lead, with the investigation file where relevant, and are not investigated by the post-holder", "better": "Referrals are made early, before a matter escalates further, with a written summary that lets the receiving manager act without reconstructing the history", "best": "Escalation judgement is trusted enough that referrals are consistently actioned on first submission with no request for missing information"}, {"name": "Pastoral first response and wellbeing identification", "dnm": "Students of concern are missed or referred late, and wellbeing risks surface only after a parent or another staff member raises them", "good": "Students of concern are identified and referred to the right owner in a timely way, with pastoral records kept current", "better": "Wellbeing risks are identified from behaviour and attendance patterns before they become urgent, with restorative practice used as the default response", "best": "Early identification of wellbeing risks in the grade is reliable enough that the Head of Prep School or Deputy Head Student Affairs treats it as an early warning point for the phase"}, {"name": "Parent and family communication", "dnm": "Parents are not the first point of contact on wellbeing and behaviour matters, communication is delayed, or matters of record are not put in writing", "good": "Parents receive timely, regular communication on wellbeing and behaviour, with concerns raised early and matters of record confirmed in writing", "better": "Communication anticipates likely parent questions and routes any matter outside the Grade Coordinator''s remit to the correct owner without the parent needing to chase", "best": "Parent communication turnaround and quality in the grade is consistently strong enough to reduce escalations reaching the Deputy Head Student Affairs or Head of Prep School directly"}, {"name": "Grade PBS coordination", "dnm": "Grade behaviour data is not reviewed regularly, positive recognition is inconsistent, or students needing Tier 2 support are not identified", "good": "Grade behaviour data is reviewed regularly, positive recognition is applied, and students who may need Tier 2 support are identified and referred to the Deputy Head Student Affairs or Head of Prep School", "better": "PBS data trends for the grade are used proactively to adjust routines and recognition before behaviour patterns worsen", "best": "The grade''s PBS data and pastoral records are consistently the most current and reliable in the phase, used as a model by other Grade Coordinators"}, {"name": "New student onboarding and co-curricular monitoring", "dnm": "New students are not onboarded consistently, or co-curricular disengagement is not noticed or flagged", "good": "New students are onboarded into the grade, co-curricular participation is monitored, and disengagement is flagged when it occurs", "better": "Onboarding and co-curricular monitoring are proactive, with grade nominations for recognition submitted on time and disengagement addressed before it becomes a pattern", "best": "Onboarding and co-curricular engagement in the grade are strong enough to be a visible point of reference for new families and staff"}]'::jsonb, '["Every safeguarding concern is escalated immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable, and is never investigated by the post-holder", "All below-threshold investigations are documented to Code of Conduct standard, including interview records and evidence", "Serious offences, and any matter that may lead to a hearing or suspension, are referred to the Deputy Head Student Affairs (Grade 8 to 12) or Head of Prep School (Grade 4 to 7) with the full investigation file, never sanctioned by the Grade Coordinator", "Behaviour incidents are logged on the PBS system accurately and within 24 hours, using restorative practice as the default response", "Student and family information is handled in line with POPIA", "Students identified as needing Tier 2 support are referred to the Deputy Head Student Affairs or Head of Prep School, not actioned directly by the Grade Coordinator", "Matters of record are communicated in writing, with parent concerns routed to the correct owner of the matter"]'::jsonb, 7),
  ('student_support_coordinator', 'Student Support Coordinator', 'Covers coordination of learning support and inclusion from Grade 4 to 12, plus post-school guidance in the High School, working to the Head of Prep School on Prep cases and to the Deputy Head Student Affairs on High School matters.', '[{"name": "Caseload management and support plan coordination", "dnm": "The D6 caseload register is inaccurate or out of date, or support plans are not reviewed on schedule", "good": "The caseload register is accurate and current, with access controls applied, and support plans are reviewed regularly against progress with families", "better": "Reviews surface progress or concerns early enough that the Head of Prep School or Deputy Head Student Affairs can adjust priorities before a plan drifts off track", "best": "Caseload accuracy and review discipline are strong enough that no student on the caseload falls between structures across a full cycle"}, {"name": "Working within sign-off boundaries", "dnm": "Support plans, ISPs, or case priorities are signed off or decided by the Coordinator directly, rather than by the Head of Prep School or Deputy Head Student Affairs", "good": "The Coordinator prepares and coordinates support plans and case priorities but routes sign-off and prioritisation decisions to the Head of Prep School (Prep cases) or Deputy Head Student Affairs (High School cases)", "better": "Recommendations to the sign-off authority are well evidenced enough that they are approved without needing revision", "best": "The sign-off relationship is trusted enough that recommendations are consistently adopted as submitted, reflecting sound judgement within the role''s delegated limit"}, {"name": "Specialist liaison and multidisciplinary coordination", "dnm": "Liaison with educational psychologists, therapists, or other specialists is inconsistent, or multidisciplinary case meetings are not documented", "good": "Liaison with specialists is maintained, multidisciplinary case meetings are held and documented, and teachers are briefed on accommodations", "better": "Specialist input is translated into practical classroom accommodations that teachers can apply without further clarification", "best": "Specialist liaison and briefing are consistently strong enough that accommodation implementation is reliable across subject teachers"}, {"name": "PBS alignment in support plans", "dnm": "Behaviour support strategies are missing from ISPs, or input to Tier 2 and Tier 3 planning for caseload students is absent or late", "good": "Behaviour support strategies are built into ISPs, with input to Tier 2 and Tier 3 planning provided for students on the caseload", "better": "Behaviour outcomes for supported students are monitored and used to adjust ISP strategies proactively", "best": "Behaviour outcomes for supported students show consistent improvement across the cycle"}, {"name": "Admissions screening and handover accuracy", "dnm": "Admissions inclusion screening recommendations are made without proper process, or the Grade 3 handover from the JP Phase Coordinator is incomplete or delayed", "good": "Admissions inclusion screening is conducted for Grade 4 to 12 with a recommendation made to the Executive Head, and the Grade 3 handover is received and reconciled", "better": "Screening recommendations and handover documentation are detailed enough that no follow-up clarification is needed from the Executive Head or JP Phase Coordinator", "best": "Handover and admissions screening accuracy is high enough that supported students move between phases with no loss of information"}, {"name": "Post-school guidance (High School)", "dnm": "Careers guidance, screenings, or university application processes are late or incomplete, with applications missing published deadlines", "good": "Careers guidance processes, screenings, and university applications are coordinated and completed on time", "better": "Students and families are kept informed proactively through the university application process, reducing last-minute issues", "best": "Post-school application completion rates and timeliness are consistently high enough to be a reliable measure of the role"}]'::jsonb, '["Every safeguarding concern is escalated immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable, and is never investigated by the Coordinator", "ISP and support plan sign-off, and case prioritisation, rest with the Head of Prep School or Deputy Head Student Affairs, never with the Coordinator alone", "The D6 learning support caseload register is maintained accurately with correct access controls, in line with POPIA", "Admissions inclusion screening produces a recommendation to the Executive Head, who makes the final decision", "The Grade 3 handover from the JP Phase Coordinator is received and reconciled without gaps", "Behaviour incidents are logged on the PBS system accurately and within 24 hours, using restorative practice as the default response", "High School post-school applications and related processes are completed within published deadlines", "Matters of record are communicated in writing, with parent concerns routed to the correct owner of the matter"]'::jsonb, 8),
  ('preschool_phase_coordinator', 'Preschool Phase Coordinator', 'Covers day-to-day pastoral, behaviour, and academic coordination for all Preschool classes, from the Nest to Grade R, on behalf of the Head of Preschool.', '[{"name": "Pastoral and first-line behaviour coordination", "dnm": "Class teachers are not supported with PBS routines, or behaviour matters that should escalate to the Head of Preschool are handled independently instead", "good": "Class teachers are supported with PBS in daily routines, and behaviour matters beyond first-line coordination are escalated to the Head of Preschool rather than decided by the Coordinator", "better": "Escalations to the Head of Preschool are timely and well documented, letting the Head act without gathering further context", "best": "Pastoral and behaviour coordination across all Preschool classes is consistent enough that class teachers rely on the Coordinator as the first point of guidance"}, {"name": "Academic support and progress monitoring", "dnm": "Planning support to teachers is inconsistent, or reports to families go out without quality checks", "good": "Teachers are supported with planning, each child''s development and progress is monitored, and reports to families receive a quality check before going out", "better": "Development monitoring identifies children needing additional support early enough for the Head of Preschool to act before a parent raises it", "best": "Academic support and monitoring across the Preschool is strong enough that report quality and consistency is noted positively by families and the Head of Preschool alike"}, {"name": "Visiting specialist and early intervention coordination", "dnm": "Visiting specialist arrangements (for example OT or speech therapy) are scheduled or changed without the Head of Preschool''s approval", "good": "Visiting specialists and early intervention are coordinated and scheduled, with final approval from the Head of Preschool sought before arrangements are confirmed", "better": "Specialist scheduling is proactive enough that sessions run without disruption to the classroom timetable", "best": "Specialist visits are consistently well documented and coordinated, giving the Head of Preschool full visibility with no gaps"}, {"name": "Assistant deployment and ratio monitoring", "dnm": "Ratios are not monitored consistently, or assistant deployment or ratio changes are made without the Head of Preschool''s authorisation", "good": "Assistant deployment rosters are managed and ratios are monitored daily, with any change to ratios or deployment referred to the Head of Preschool for authorisation", "better": "Ratio monitoring identifies pressure points early enough for the Head of Preschool to adjust deployment before a ratio issue arises", "best": "Deployment and ratio management is reliable enough across the Preschool that ratio compliance is never in question"}, {"name": "Parent contact and PBS logging", "dnm": "Routine parent contact is delayed, or PBS incidents are logged late, inaccurately, or not at all", "good": "Routine pastoral matters are the Coordinator''s first point of parent contact, and PBS incidents are logged accurately and promptly", "better": "Parent response turnaround is consistently fast, and PBS records are current enough to support Head of Preschool reporting without follow-up", "best": "Parent contact and PBS logging quality across the Preschool is strong enough to be the phase benchmark"}, {"name": "Grade R transition records", "dnm": "Grade R transition records for Grade 1 are incomplete or delivered late", "good": "Grade R transition records are prepared and handed over to Grade 1 accurately and on time", "better": "Transition records include enough detail that Grade 1 teachers need no follow-up questions", "best": "Transition handover is consistently strong enough that Grade 1 teachers cite it as a smooth start to the year"}]'::jsonb, '["Every safeguarding concern is escalated immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable", "PBS incidents across all Preschool classes are logged accurately and within 24 hours", "Ratio monitoring is recorded daily, and any ratio change or breach is referred to the Head of Preschool for authorisation, never actioned independently", "Visiting specialist and early intervention arrangements receive final approval from the Head of Preschool before being confirmed", "Student and family information is handled in line with POPIA", "Grade R transition records are completed and current ahead of the Grade 1 handover", "Behaviour matters at Tier 2 and Tier 3 are referred to the Head of Preschool, not decided by the Coordinator"]'::jsonb, 9),
  ('jp_phase_coordinator', 'JP Phase Coordinator', 'Covers academic and student affairs coordination for Grade 1 to 3, on behalf of the Head of Prep School.', '[{"name": "Assessment calendar and benchmark coordination", "dnm": "The assessment calendar, moderation, or reading and numeracy benchmarks are not maintained, or progress reporting to families is late", "good": "The assessment calendar and moderation process are maintained, benchmarks are tracked for Grade 1 to 3, and progress reporting to families is coordinated on schedule", "better": "Benchmark data is reviewed proactively during the term, allowing intervention before a reporting cycle exposes a gap", "best": "Benchmark progress and on-time reporting across Grade 1 to 3 is consistently strong enough to be the reference standard for the phase"}, {"name": "Pastoral and behaviour coordination", "dnm": "Pastoral or behaviour matters requiring escalation are handled independently instead of being referred to the Head of Prep School, or first-line parent contact is inconsistent", "good": "Pastoral and behaviour coordination is maintained for Grade 1 to 3, with first-line parent contact handled directly and matters beyond that referred to the Head of Prep School", "better": "Referrals to the Head of Prep School are timely and well documented, allowing quick action without further information gathering", "best": "Pastoral and behaviour coordination in the JP phase is consistent enough that parents and staff see it as a reliable first point of contact"}, {"name": "PBS coordination and referral judgement", "dnm": "PBS routines and recognition systems are applied inconsistently across Grade 1 to 3, or behaviour data is not referred to the Head of Prep School when needed", "good": "PBS routines, recognition systems, and behaviour data are coordinated consistently across Grade 1 to 3, with referral to the Head of Prep School where appropriate", "better": "PBS data trends are used to adjust routines proactively before behaviour patterns become a concern", "best": "PBS data across Grade 1 to 3 is consistently current and used by the Head of Prep School as a reliable early indicator for the phase"}, {"name": "Learning support coordination", "dnm": "Support to the Head of Prep School on learning support matters in Grade 1 to 3 is inconsistent or reactive only", "good": "The Head of Prep School is supported consistently on learning support matters in Grade 1 to 3", "better": "Learning support needs are flagged early enough for the Head of Prep School to act before a concern affects a child''s progress", "best": "Learning support coordination in Grade 1 to 3 is strong enough that transitions into formal support structures are smooth and well documented"}, {"name": "Grade 3 to 4 handover", "dnm": "The Grade 3 to 4 handover to the Student Support Coordinator and Grade 4 Grade Coordinator is incomplete, inaccurate, or late", "good": "The Grade 3 to 4 handover is completed accurately and on schedule, covering both the Student Support Coordinator and the Grade 4 Grade Coordinator", "better": "Handover documentation is detailed enough that the receiving Coordinators need no follow-up clarification", "best": "Handover quality is consistently strong enough that Grade 4 pick-up of students is seamless, with no information lost at the transition"}, {"name": "Intern and assistant deployment", "dnm": "Deployment rosters for interns and assistants are not maintained, or deployment exceeds the approved roster", "good": "Deployment rosters for interns and assistants are maintained and kept within the approved roster", "better": "Deployment is adjusted proactively to match daily needs across Grade 1 to 3 classes", "best": "Deployment management is reliable enough to be a model for roster planning in the Prep School"}]'::jsonb, '["Every safeguarding concern is escalated immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable", "Behaviour incidents are logged on the PBS system accurately and within 24 hours, using restorative practice as the default response", "Disciplinary decisions in Grade 1 to 3 are referred to the Head of Prep School, never taken by the Coordinator", "The assessment calendar, moderation, and benchmark reporting deadlines are met, with records kept current", "The Grade 3 to 4 handover to the Student Support Coordinator and Grade 4 Grade Coordinator is completed accurately and on schedule", "Student and family information is handled in line with POPIA", "Intern and assistant deployment stays within the approved roster", "Matters of record are communicated in writing, with parent concerns routed to the correct owner of the matter"]'::jsonb, 10),
  ('stay_and_play_coordinator', 'Stay and Play Coordinator', 'Covers the Stay and Play Coordinator, responsible for the Preschool after-school activity programme, reporting to the Head of Preschool.', '[{"name": "Activity programme planning and handover", "dnm": "Activity plans are absent or out of date, or handover from class teachers is not checked against the register.", "good": "An activity plan is in place for each session, and every child is received from class teachers against a completed register.", "better": "Activity plans are varied and matched to the developmental needs of different Preschool age groups within Stay and Play.", "best": "The activity planning approach is documented well enough that another staff member could run a session from it without additional briefing."}, {"name": "Authorised sign-out and collection", "dnm": "A child is released, or nearly released, to someone not on the authorised collector list, or the late and unauthorised collection procedure is not applied.", "good": "Children are signed out only to authorised collectors, with every collection recorded and the late and unauthorised collection procedure applied consistently.", "better": "Discrepancies in collector information are queried with the Head of Preschool proactively, before they become a same-day pickup issue.", "best": "Zero unauthorised releases are sustained across the review period, evidenced by complete sign-out records."}, {"name": "Ratio checks and escalation", "dnm": "Ratios are not checked at every session, or shortfalls are not reported to the Head of Preschool.", "good": "Ratios are checked at every session, and any shortfall is reported to the Head of Preschool immediately.", "better": "Potential ratio shortfalls, such as staff absence or high enrolment on a given day, are flagged in advance so cover can be arranged.", "best": "A consistent record of ratio compliance is maintained across the term, with any escalation documented through to resolution."}, {"name": "Allergy and dietary information management", "dnm": "Allergy or dietary information is missing, out of date, or not checked before a session.", "good": "Current allergy and dietary information is held and checked for every child in Stay and Play.", "better": "Allergy and dietary records are reviewed and updated proactively at the start of each term, not only when a child joins.", "best": "The allergy and dietary record-keeping process is used as a reference example for other after-school care staff."}, {"name": "PBS practice in Stay and Play", "dnm": "Routines are inconsistent, positive recognition is rarely used, or incidents are recorded late or inaccurately.", "good": "Routines are consistent, positive recognition is used regularly, and incidents are recorded accurately and promptly.", "better": "Restorative conversations are used as the first response to behaviour incidents in Stay and Play, consistent with PBS benchmarks.", "best": "The Coordinator is a visible model of PBS-aligned practice in Stay and Play, and other rostered staff look to this role for guidance."}, {"name": "Injury, safety reporting and family communication", "dnm": "Injuries, first aid given or safety concerns are not reported on the day, or families are not kept informed of their child''s time in Stay and Play.", "good": "Injuries, first aid given and safety concerns are reported on the day, and families receive timely communication on their child''s time in Stay and Play.", "better": "Families receive proactive, specific updates, not only when something goes wrong, that build confidence in the programme.", "best": "The Coordinator is the trusted first point of parent contact on Stay and Play matters, with a record of resolving queries without escalation."}]'::jsonb, '["Children are signed out only to authorised collectors on the register, with the late and unauthorised collection procedure applied without exception.", "Ratios are checked at every Stay and Play session, and any shortfall is reported to the Head of Preschool immediately.", "Current allergy and dietary information is held and checked for every child before each session.", "PBS incidents are recorded on the PBS system accurately and within 24 hours, using restorative practice as the default response.", "Every safeguarding concern is reported immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable.", "Student and family information is handled in line with POPIA.", "Registers and sign-out records are complete for every session.", "Injuries, first aid given and safety concerns are reported on the day they occur."]'::jsonb, 11),
  ('aftercare_manager', 'Aftercare Manager', 'Covers the Aftercare Manager, responsible for Grade 1 to 7 aftercare and Preschool and Prep School holiday care, reporting to the Head of Prep School and directing aftercare assistants.', '[{"name": "Safe running of sessions, registers and handover", "dnm": "Attendance registers are incomplete, or the handover of children from class teachers into aftercare is not consistently checked.", "good": "Attendance registers are completed for every session, and children are received from class teachers into aftercare against a checked handover.", "better": "Handover and registration processes are adjusted proactively when session patterns change, such as holiday care volumes, keeping records complete without prompting.", "best": "Registers and handover records are complete and audit-ready across every session, cited as a model by the Head of Prep School."}, {"name": "Authorised sign-out and collection", "dnm": "A child is released, or nearly released, to someone not on the authorised collector list, or collections are not consistently recorded.", "good": "Children are released only to authorised collectors, every collection is recorded, and the late and unauthorised collection procedure is applied consistently.", "better": "Collector information issues are queried with families in advance of pickup, reducing same-day sign-out problems.", "best": "Zero unauthorised releases are sustained across the review period, with complete sign-out records as evidence."}, {"name": "Supervision ratios, including holiday care", "dnm": "Ratios, including partial care ratios for Preschool children in holiday care, are not consistently maintained or checked.", "good": "Supervision ratios, including partial care ratios for Preschool children in holiday care, are maintained and checked at every session.", "better": "Staffing is planned ahead of high-demand holiday care periods so ratio compliance does not depend on last-minute cover.", "best": "Ratio compliance is sustained across term-time aftercare and holiday care with no recorded shortfalls."}, {"name": "Food safety and allergy or dietary management", "dnm": "Food is served without each child''s allergy and dietary information being checked, or checks are inconsistent.", "good": "Each child''s allergy and dietary information is checked before food is served, at every session.", "better": "Allergy and dietary records for aftercare and holiday care are reviewed and updated proactively each term.", "best": "Food safety and allergy checking practice is used as the reference standard for other care-based roles."}, {"name": "PBS practice and deployment of assistants", "dnm": "Expectations in aftercare are applied inconsistently across assistants, or incidents are recorded late or inaccurately.", "good": "Consistent PBS expectations, positive recognition and restorative first responses are applied across aftercare and holiday care, with incidents recorded accurately and promptly.", "better": "Aftercare-only and rostered classroom assistants are actively coached on PBS practice so standards hold when the manager is not directly present.", "best": "The Manager is a visible model of PBS-aligned aftercare practice, with deployment and supervision of assistants producing consistently high standards across sessions."}, {"name": "Holiday care planning and family communication", "dnm": "The holiday care activity programme is planned late or without input from the Head of Preschool for Preschool children, or family communication is irregular.", "good": "A holiday care activity programme is planned in advance, with input from the Head of Preschool for Preschool children, and families receive timely, regular communication on aftercare and holiday care.", "better": "Holiday care programming responds to parent feedback from previous terms, evidenced in changes made.", "best": "Parent feedback on aftercare and holiday care is consistently positive and used to shape the following term''s programme."}]'::jsonb, '["Children are released only to authorised collectors on the register, with every collection recorded and the late and unauthorised collection procedure applied without exception.", "Supervision ratios, including partial care ratios for Preschool children in holiday care, are maintained and checked at every session.", "Each child''s allergy and dietary information is checked before food is served, at every session.", "PBS incidents are recorded on the PBS system accurately and within 24 hours, using restorative practice as the default response.", "Every safeguarding concern is reported immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable, including during holiday periods.", "Student and family information is handled in line with POPIA.", "Registers and sign-out records are complete for every session.", "Injuries, first aid given and safety concerns are reported on the day they occur."]'::jsonb, 12),
  ('head_of_sports', 'Head of Sports', 'Covers the Head of Sports, responsible for the whole-school sport and PE programme, reporting to the Executive Head and line managing sports coaches and PE teachers.', '[{"name": "Sport and PE programme, fixtures and selection policy", "dnm": "The fixture programme, selection policy or coaching standards are inconsistently applied, or documented late.", "good": "A fixture programme is in place each term, selection policy is applied consistently, and coaching standards are documented and communicated to coaches and PE teachers.", "better": "The programme is adjusted proactively based on participation data or coach feedback to improve fit across age groups and sports.", "best": "The sport and PE programme is evidenced to increase participation year on year, with selection decisions consistently defensible against policy."}, {"name": "Line management of coaches and PE teachers", "dnm": "Coaches and PE teachers receive little or inconsistent oversight, and capability issues are not addressed.", "good": "Coaches and PE teachers are actively managed against coaching standards, with capability issues identified and addressed.", "better": "Coach development needs are identified proactively and addressed through targeted support or training.", "best": "Coach capability is consistently strong across the department, evidenced in observed session quality and parent feedback."}, {"name": "Safety in sport", "dnm": "Supervision ratios or equipment checks are inconsistently followed at training or fixtures, or injuries are not reported promptly.", "good": "Supervision ratios and equipment checks are followed at every training session and fixture, and injuries are reported promptly.", "better": "Safety risks specific to particular sports or venues are identified and addressed before they result in an incident.", "best": "Safety incidents in sport are at or near zero across the review period, with a documented, consistently applied safety process behind the result."}, {"name": "PBS practice in sport", "dnm": "Expectations at training and fixtures are applied inconsistently, or PBS incidents in sport are recorded late or inaccurately.", "good": "Consistent expectations are applied at training and fixtures, positive recognition is used, and PBS incidents in sport are recorded accurately and promptly.", "better": "Coaches and PE teachers are actively coached on PBS practice so standards hold consistently across training sessions and fixtures.", "best": "The Head of Sports is a visible model of PBS-aligned practice in sport, and coaches and PE teachers are directed to this example for guidance."}, {"name": "Sports awards and colours criteria", "dnm": "Awards or colours are allocated inconsistently against criteria, or criteria are not clearly documented.", "good": "Sports awards and colours are allocated against documented criteria, applied consistently across sports.", "better": "Awards and colours criteria are reviewed each year to keep them fair and current across the range of sports offered.", "best": "The awards and colours process is consistently defensible under scrutiny, with no upheld disputes over criteria application."}, {"name": "Family communication", "dnm": "Families are not kept informed of selection, fixtures, results or their child''s progress in sport, or updates are late.", "good": "Families receive timely communication on selection, fixtures, results and their child''s progress in sport.", "better": "Communication anticipates likely parent questions, such as selection decisions or fixture changes, rather than only responding after the fact.", "best": "Parent feedback on sport is consistently positive, reflecting confidence in how selection and communication are handled."}]'::jsonb, '["Supervision ratios and equipment checks are completed at every training session and fixture.", "Injuries and safety incidents in sport are reported on the day they occur.", "PBS incidents in sport are recorded on the PBS system accurately and within 24 hours, using restorative practice as the default response.", "Every safeguarding concern is reported immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable.", "Student and family information is handled in line with POPIA.", "Sports awards and colours are allocated against documented, consistently applied criteria.", "Selection decisions are made within policy and are documented."]'::jsonb, 13),
  ('learn_to_swim_teacher', 'Learn to Swim Teacher', 'Covers the Learn to Swim Teacher, responsible for the Preschool Learn to Swim programme from 2 years (from 12 months once 0 to 2 certification is complete), reporting to the Head of Preschool.', '[{"name": "Lesson planning and teaching by age group", "dnm": "Lessons are not planned to suit the age group, or are delivered without a clear plan.", "good": "Learn to Swim lessons are planned and taught appropriately for each age group.", "better": "Grouping of children by ability is used to keep lessons appropriately paced and challenging.", "best": "Lesson planning consistently produces measurable swimming progress across age groups, evidenced in progress records."}, {"name": "Water safety supervision and equipment checks", "dnm": "Supervision ratios in and around the pool, or pool and equipment checks before lessons, are inconsistently followed.", "good": "Supervision ratios in and around the pool are maintained, and pool and equipment checks are completed before every lesson.", "better": "A lesson is stopped or postponed on safety grounds when conditions warrant it, ahead of any incident occurring.", "best": "Zero water safety incidents are sustained across the review period, with checks consistently documented."}, {"name": "Certification currency", "dnm": "Swimming instruction, first aid or lifesaving certification lapses, or 0 to 2 certification is not in place before teaching children from 12 months.", "good": "Swimming instruction, first aid and lifesaving certification are kept current, with 0 to 2 certification completed before lessons start for children from 12 months.", "better": "Certification renewal is scheduled well ahead of expiry so there is no risk of a lapse affecting the lesson programme.", "best": "Certification records are consistently current and available on request, with no gaps across the review period."}, {"name": "Allergy and dietary information management", "dnm": "Allergy or dietary information is missing, out of date, or not checked before a lesson.", "good": "Current allergy and dietary information is held and checked for every child in the lesson.", "better": "Allergy and dietary records are reviewed proactively at the start of each term rather than only when a child joins.", "best": "Allergy and dietary record-keeping in Learn to Swim is used as a reference example for other Preschool staff."}, {"name": "Progress monitoring and communication", "dnm": "Swimming progress is not monitored consistently, or is not communicated to class teachers and families.", "good": "Each child''s swimming progress is monitored and communicated to class teachers and families.", "better": "Progress communication is specific enough that families and class teachers can see a clear trajectory by age group, not only a general update.", "best": "Swimming progress by age group is consistently evidenced and used to inform lesson grouping and planning decisions."}, {"name": "PBS practice and incident reporting", "dnm": "PBS incidents in swimming lessons are recorded late or inaccurately, or injuries are not reported immediately.", "good": "PBS incidents in swimming lessons are recorded accurately and promptly, and injuries and incidents are reported immediately with families informed promptly.", "better": "Restorative practice is used consistently as the first response to behaviour incidents during lessons.", "best": "The Teacher is a visible model of PBS-aligned, safety-first practice in Learn to Swim, and other Preschool staff look to this example for guidance."}]'::jsonb, '["Swimming instruction, first aid and lifesaving certification are kept current at all times, including 0 to 2 certification completed before any lesson is taught to a child from 12 months.", "Pool and equipment checks are completed before every lesson.", "Supervision ratios in and around the pool are maintained at every lesson.", "Current allergy and dietary information is checked for every child before each lesson.", "PBS incidents are recorded on the PBS system accurately and within 24 hours, using restorative practice as the default response.", "Injuries and incidents are reported immediately, with families informed promptly.", "Every safeguarding concern is reported immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable.", "Student and family information is handled in line with POPIA."]'::jsonb, 14),
  ('aftercare_assistant', 'Aftercare Assistant', 'Covers the Aftercare Assistant, supporting the Aftercare Manager with aftercare (Grade 1 to 7) and holiday care (Preschool and Prep School) supervision, homework time, meals and safe collection.', '[{"name": "Active supervision within ratios", "dnm": "Supervision ratios are not maintained indoors or outdoors, or children are left without active supervision at any point.", "good": "Active supervision within ratios is maintained consistently, both indoors and outdoors.", "better": "Positioning and attention are adjusted proactively as activities or groups change, keeping supervision effective without being directed to do so.", "best": "Sustained, reliable active supervision across every session, consistently noted by the Aftercare Manager as requiring no correction."}, {"name": "Homework period support", "dnm": "The homework period is not consistently supported, or the assistant teaches or marks work outside the role''s boundary.", "good": "The homework period is supported consistently, without teaching or marking, consistent with the role boundary.", "better": "Children who are struggling to settle into homework time are identified and supported to stay on task, without stepping into a teaching role.", "best": "The Assistant consistently manages the homework period so it runs smoothly with minimal disruption, freeing other staff to focus on supervision elsewhere."}, {"name": "Food service and allergy or dietary compliance", "dnm": "Food is served without checking a child''s allergy and dietary information, or hygiene practice is inconsistent.", "good": "Food is served hygienically, following each child''s allergy and dietary information every time.", "better": "Potential allergy or dietary mismatches are queried with the Aftercare Manager before food is served, not after.", "best": "Consistently reliable food safety practice across every session, with no recorded allergy or dietary errors."}, {"name": "Supporting authorised sign-out", "dnm": "A child is released, or nearly released, without checking the authorised collector register, or sign-out support is inconsistent.", "good": "Sign-out is supported consistently against the authorised collector register, as directed by the Aftercare Manager.", "better": "Unclear or unfamiliar collectors are flagged to the Aftercare Manager proactively before release is considered.", "best": "Zero unauthorised releases supported across the review period, with sign-out procedure followed reliably every time."}, {"name": "PBS routine application and incident reporting", "dnm": "PBS routines are applied inconsistently, or incidents are not reported to the Aftercare Manager promptly.", "good": "PBS routines are applied consistently, and incidents are reported to the Aftercare Manager promptly.", "better": "Positive recognition consistent with PBS is used proactively to prevent minor behaviour issues escalating.", "best": "The Assistant is a reliable, consistent model of PBS-aligned practice that the Aftercare Manager can depend on without follow-up checking."}, {"name": "Injury and safety reporting", "dnm": "Injuries, first aid given or safety concerns are not reported immediately.", "good": "Injuries, first aid given and any safety concern are reported immediately.", "better": "Potential safety concerns, such as trip hazards or equipment issues, are flagged proactively before they cause an incident.", "best": "Consistently prompt and accurate safety reporting across every session, with no gaps identified by the Aftercare Manager."}]'::jsonb, '["Supervision ratios are maintained at all times, indoors and outdoors.", "Food is served hygienically, following each child''s allergy and dietary information, every time.", "No child is released to anyone not on the authorised collector list; sign-out is only carried out as directed by the Aftercare Manager.", "PBS incidents are reported to the Aftercare Manager promptly, and logged on the PBS system within 24 hours.", "Injuries, first aid given and any safety concern are reported immediately.", "Every safeguarding concern is reported immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable.", "Student and family information is handled in line with POPIA.", "The homework period is supported without teaching or marking, consistent with the role boundary."]'::jsonb, 15),
  ('preschool_teacher', 'Preschool Teacher', 'Covers class teachers responsible for a single class from the Nest to Grade R, including care routines, health and allergy records, and daily parent communication.', '[{"name": "Planning and instructional delivery", "dnm": "Session plans for the class programme, including PE and music, are absent or not followed, and daily routines are not delivered as planned", "good": "Delivers the planned programme for the class, including PE and music, with session plans available on request", "better": "Adapts the daily programme in response to how the group is engaging, and coordinates smoothly with the Stay and Play Coordinator and Learn to Swim Teacher on handovers", "best": "Programme delivery is used as a model by colleagues; consistently produces well organised sessions that other preschool teachers ask to observe or borrow from"}, {"name": "Care routines, health and allergy management", "dnm": "Care routines (nappy changing, toileting, feeding, sleep and rest) are inconsistently followed, or allergy and dietary information is missing, out of date, or not checked before food is given", "good": "Follows care routines consistently with the assistants, keeps each child''s allergy and dietary information current, and checks it whenever food is given", "better": "Proactively confirms that everyone responsible for a child''s food, care and activities, including relief staff, has current allergy information before the need arises", "best": "Maintains a class record of care and allergy information that other staff and relief cover rely on without needing to double check; medicine and dosage records are complete and error free over the review period"}, {"name": "Developmental observation and progress reporting", "dnm": "Developmental observations are not current, or progress reports to families are late or inaccurate", "good": "Keeps observations of each child''s development current and reports progress to families accurately and on time", "better": "Uses observations to adjust activities for individual children, and flags emerging developmental concerns to the Head of Preschool early", "best": "Observation and reporting practice is used as an example for other preschool teachers; families consistently describe reports as clear and accurate"}, {"name": "PBS and behaviour support", "dnm": "PBS routines are applied inconsistently in the classroom, or incident records are late, inaccurate or missing", "good": "Applies PBS routines and positive reinforcement consistently, responds to incidents using restorative practice, and keeps accurate, prompt records", "better": "Escalates emerging behaviour patterns to the Phase Coordinator and Head of Preschool before they become incidents, and coaches assistants in applying PBS routines", "best": "Is regarded by the Head of Preschool as a reliable PBS practitioner whose class records need no follow up or correction"}, {"name": "Relationships and communication with families", "dnm": "Communication with families about a child''s day, wellbeing or learning is irregular or unprofessional, or families are not informed promptly when a child is ill or needs to go home", "good": "Communicates with families regularly and professionally about each child''s day, wellbeing and learning, and informs families promptly, and consistently, when a child is ill or needs to go home", "better": "Supports new children and their families through settling in with visible care, and keeps the Head of Preschool informed of children sent home without being prompted", "best": "Is sought out by families as a trusted point of contact for their child''s wellbeing and development"}, {"name": "Contribution to preschool life", "dnm": "Rostered Stay and Play duties are missed or delivered without preparation, or Grade R school readiness collaboration with Grade 1 teachers does not happen", "good": "Delivers Stay and Play activities when rostered, and, where teaching Grade R, works with the Head of Preschool and Grade 1 teachers on school readiness", "better": "Contributes ideas that improve Stay and Play or school readiness handover beyond the minimum expected", "best": "Handovers to Grade 1 are so well prepared that receiving teachers cite them as making the transition noticeably smoother"}]'::jsonb, '["Safeguarding clearance and background checks current", "Medicine administered only with written parental consent, with every dose recorded", "Allergy and dietary information current for every child and shared with everyone responsible for that child''s food, care and activities", "PBS incidents recorded accurately and promptly, with restorative practice as the default response", "Families informed promptly when a child is ill or needs to go home, and the Head of Preschool kept informed", "Student and family information handled in line with POPIA", "Signed review documentation on file for every review cycle", "Developmental observations and progress reports submitted accurately and on time"]'::jsonb, 16),
  ('preschool_assistant', 'Preschool Assistant', 'Covers assistants supporting the class teacher with supervision, care routines and lessons from the Nest to Grade R.', '[{"name": "Supervision and care routines", "dnm": "Supervision falls outside agreed ratios, indoors or outdoors, or care routines (nappy changing, toileting, feeding, sleep and rest) are not followed as directed by the teacher", "good": "Maintains active supervision within ratios at all times, indoors and outdoors, and follows care routines as directed by the teacher", "better": "Anticipates care needs before being asked, and adjusts supervision positioning to cover gaps as the group moves between activities", "best": "Is trusted by teachers to run care routines and supervision without oversight, freeing the teacher to focus on instruction"}, {"name": "Supporting lessons and delegated activities", "dnm": "Support for lessons (leading songs, helping children with tasks) is inconsistent, or, in Grade R, delegated activities or locum core subject teaching are delivered without following the teacher''s plans", "good": "Supports lessons reliably, leading songs and helping children with tasks, and in Grade R delivers delegated activities, or locum teaching, from the teacher''s plans and oversight", "better": "Adjusts support to individual children''s needs during lessons, and prepares for locum cover proactively when notified in advance", "best": "Delivers delegated and locum sessions so smoothly that they are indistinguishable in quality from the class teacher''s own delivery"}, {"name": "Allergy and dietary information", "dnm": "Allergy and dietary information is not followed when food is given, or a change reported by a family is not passed to the teacher", "good": "Follows each child''s allergy and dietary information whenever food is given, and tells the teacher at once of any change a family reports", "better": "Cross checks allergy information independently before mealtimes and flags discrepancies before they become a risk", "best": "Is relied on by the teacher as a second check on allergy and dietary safety, with no missed changes over the review period"}, {"name": "PBS application and reporting", "dnm": "PBS routines are not applied as modelled by the teacher, or incidents and developmental observations are not reported promptly", "good": "Applies PBS routines as modelled by the teacher, and reports incidents and observations, including those that inform a child''s progress, promptly", "better": "Notices and reports early signs of behaviour or developmental change before they are visible to the teacher", "best": "Observations are specific and detailed enough that the teacher uses them directly in progress reporting without needing to follow up"}, {"name": "Relationships and communication", "dnm": "Interactions with children, colleagues or the teacher are inconsistently respectful or professional, or the assistant communicates with parents beyond routine handovers without referring to the teacher", "good": "Is respectful and professional with children and colleagues, and refers parent communication beyond routine handovers to the class teacher", "better": "Builds positive relationships with children that support settling in and daily routines, and communicates clearly with the teacher on handover", "best": "Is a source of reassurance for children and families during handovers and transitions, and is sought out by the teacher as a dependable second pair of hands"}, {"name": "Contribution to preschool life", "dnm": "Rostered Stay and Play duties are missed or not supported as required", "good": "Supports Stay and Play activities when rostered", "better": "Takes initiative in Stay and Play sessions beyond the minimum rostered task", "best": "Contribution to Stay and Play is specifically noted by the Coordinator as strengthening the programme"}]'::jsonb, '["Safeguarding clearance and background checks current", "Ratios maintained at all times, indoors and outdoors", "Allergy and dietary information followed for every child, with changes reported to the teacher immediately", "PBS incidents and observations reported to the teacher promptly", "Does not administer medicine or communicate with parents beyond routine handovers", "Student and family information handled in line with POPIA", "Signed review documentation on file for every review cycle"]'::jsonb, 17),
  ('teacher', 'Teacher', 'Covers class or subject teachers from Grade 1 to 12 who plan, teach, assess and care for students, and who direct interns and assistants in the classroom.', '[{"name": "Planning and instructional delivery", "dnm": "Planning and delivery fall below the subject or phase standard, or lesson plans are not available when requested", "good": "Plans and delivers lessons to the subject or phase standard, with plans available on request", "better": "Adapts delivery within the scheme of work in response to how students are progressing, and shares effective approaches with colleagues", "best": "Planning and delivery are used as a model within the subject or phase, and is sought out by colleagues for guidance on lesson design"}, {"name": "Assessment, marking and student progress", "dnm": "Assessment and marking fall below the subject or phase standard, or progress reports to families are late or inaccurate", "good": "Assesses and marks to the subject or phase standard, and monitors, reports and communicates each student''s progress to families accurately and on time", "better": "Uses assessment data to identify students needing additional support early, and adjusts teaching in response", "best": "Assessment and reporting practice is consistently accurate enough that it requires no correction or follow up from the Subject Head or Grade Coordinator"}, {"name": "Classroom PBS and behaviour management", "dnm": "Classroom expectations are not taught or reinforced consistently, or PBS incident records are late, inaccurate or missing", "good": "Teaches and reinforces classroom expectations, uses positive recognition, responds to incidents using restorative practice as the default, and keeps accurate, prompt PBS records", "better": "Identifies and addresses emerging behaviour patterns before they require escalation, and refers appropriately to the Grade Coordinator when a response is beyond classroom level", "best": "Classroom climate is consistently positive enough that it is cited by the Grade Coordinator or Deputy Head as an example of PBS in practice"}, {"name": "Relationships and communication with families", "dnm": "Parent queries go unanswered beyond the school''s agreed turnaround time, or interactions with students, parents or colleagues are inconsistently respectful or professional", "good": "Responds to parent queries within the school''s agreed turnaround time, and is respectful and professional with students, parents and colleagues", "better": "Communicates proactively with parents about class or subject matters and raises concerns early, not only when problems arise, and collaborates constructively with interns and assistants", "best": "Is sought out by parents and colleagues as a trusted point of contact, and actively supports colleagues'' communication with families in difficult situations"}, {"name": "Direction and supervision of interns and assistants", "dnm": "Interns or assistants in the classroom are left without clear direction, or their work is not reviewed", "good": "Directs and supervises interns and assistants in the classroom, giving clear tasks and reviewing their work", "better": "Actively develops interns and assistants by giving constructive feedback and increasing responsibility as their competence grows", "best": "Interns and assistants supervised report the mentoring as a significant factor in their own development"}, {"name": "Professional growth and contribution to school life", "dnm": "Rostered co-curricular and pastoral duties are missed or delivered without preparation", "good": "Fulfils rostered co-curricular and pastoral duties reliably", "better": "Takes on additional co-curricular or pastoral responsibility beyond the minimum rostered, and engages in professional development relevant to the role", "best": "Co-curricular or pastoral contribution is specifically recognised by the Head of School as strengthening school life beyond the classroom"}]'::jsonb, '["Safeguarding clearance and background checks current", "Lesson plans and schemes of work available for every class or subject taught", "Assessment and marking completed to the subject or phase standard and schedule, with reports submitted on time", "PBS incidents logged accurately within 24 hours, using restorative practice as the default response", "Student and family information handled in line with POPIA", "Signed review documentation on file for every review cycle", "Rostered co-curricular and pastoral duties fulfilled", "Concerns beyond classroom PBS responses, diagnosis of learning needs, and escalated parent disputes referred to the appropriate role rather than handled independently"]'::jsonb, 18),
  ('intern', 'Intern', 'Covers developing teachers in Prep School and High School who plan and teach under a mentor teacher''s supervision, building towards a full teaching role.', '[{"name": "Planning and teaching under supervision", "dnm": "Lessons or small groups delegated by the mentor teacher are delivered without following the agreed plan, or delivered without the mentor''s oversight where required", "good": "Plans and teaches delegated lessons and small groups as directed by the mentor teacher, within the agreed lesson plan", "better": "Seeks feedback from the mentor teacher proactively and visibly applies it in the next lesson", "best": "Progression in planning and delivery is clear enough that the mentor teacher recommends increased teaching responsibility ahead of schedule"}, {"name": "Supervision of students", "dnm": "Supervision of students falls outside the ratios or policy that apply to the role", "good": "Supervises students within the ratios and policy that apply to the role", "better": "Maintains calm, attentive supervision even during delegated small group or lesson delivery, without needing reminders from the mentor", "best": "Is trusted by the mentor teacher to supervise delegated groups with no additional oversight required"}, {"name": "PBS application and reporting", "dnm": "PBS language and routines are not applied as modelled by the mentor teacher, or incidents are not recorded or reported promptly", "good": "Applies PBS language and routines as modelled by the mentor teacher, and records or reports incidents promptly", "better": "Applies PBS routines consistently enough that the mentor teacher does not need to intervene during delegated sessions", "best": "PBS practice is cited by the mentor teacher as ready for a full teaching role without further coaching"}, {"name": "Marking and contribution to progress monitoring", "dnm": "Marking delegated by the mentor teacher is incomplete, late, or requires significant correction, or contribution to monitoring student progress is minimal", "good": "Completes delegated marking for the mentor teacher''s review, and contributes to monitoring students'' progress as delegated", "better": "Marking requires only minor adjustment from the mentor teacher, and progress contributions are specific and useful", "best": "Marking is accurate enough that the mentor teacher relies on it with minimal review"}, {"name": "Professional development", "dnm": "Induction, CPD or review meetings on the development plan are missed or attended without engagement", "good": "Attends induction, CPD and review meetings on the development plan", "better": "Acts visibly on feedback from review meetings between cycles, and seeks out additional development opportunities", "best": "Development is progressing ahead of the plan, as reflected in the mentor teacher''s and Head of School''s assessment"}]'::jsonb, '["Safeguarding clearance and background checks current", "Does not take sole responsibility for a class beyond what policy and ratios permit", "Does not sign off reports or assessment marks independently; all marking reviewed by the mentor teacher", "Does not answer parent queries independently; queries referred to the mentor teacher", "PBS incidents recorded or reported promptly", "Student and family information handled in line with POPIA", "Attends induction, CPD and review meetings on the development plan, with signed review documentation on file for every cycle"]'::jsonb, 19),
  ('teaching_assistant', 'Teaching Assistant', 'Covers assistants in Grade 1 to 3 who support the class teacher with care, supervision, routines and preparation, and who may teach non-core subjects or locum core subjects.', '[{"name": "Care routines and active supervision", "dnm": "Supervision falls outside ratios, or care routines are not maintained as required", "good": "Maintains active supervision within ratios, and follows care routines consistently", "better": "Anticipates care and supervision needs during transitions between activities without being prompted", "best": "Is trusted by the class teacher to manage care routines and supervision independently during delegated periods"}, {"name": "Preparation of materials and learning environment", "dnm": "Materials or the learning environment are not prepared as directed, or preparation is late enough to disrupt the lesson", "good": "Prepares materials and the learning environment as directed by the class teacher, ready for the lesson", "better": "Prepares materials ahead of when they are needed and flags shortages or issues to the teacher before they become a problem", "best": "Preparation is consistently ready well ahead of need, freeing the teacher to focus entirely on instruction"}, {"name": "Reinforcing learning and non-core teaching", "dnm": "Small group reinforcement or non-core teaching under the teacher''s oversight is delivered inconsistently with the teacher''s direction", "good": "Reinforces learning with small groups as directed, and teaches non-core subjects or activities under the class teacher''s oversight", "better": "Adjusts small group reinforcement to individual students'' needs, and gives the teacher useful feedback on how students responded", "best": "Small group and non-core teaching is of a quality that the class teacher relies on as equivalent to their own delivery"}, {"name": "Locum teaching of core subjects", "dnm": "Locum cover of core subjects is delivered without following the absent teacher''s plans, or without being arranged through the Phase Coordinator", "good": "Delivers locum teaching of core subjects from the absent teacher''s plans, as arranged by the Phase Coordinator", "better": "Locum cover is delivered smoothly enough that the returning teacher reports no loss of continuity", "best": "Is specifically requested for locum cover by the Phase Coordinator because of consistent reliability"}, {"name": "PBS application and reporting", "dnm": "PBS routines are not applied consistently as modelled by the class teacher, or incidents and observations are not reported promptly", "good": "Applies PBS routines consistently as modelled by the class teacher, and reports incidents and observations, including those that inform students'' progress, promptly", "better": "Notices and reports early signs of behaviour or learning difficulty before they are visible to the teacher", "best": "Observations are specific and detailed enough that the teacher uses them directly in progress reporting without needing to follow up"}, {"name": "Relationships, communication and contribution to school life", "dnm": "Interactions with students or colleagues are inconsistently respectful or professional, or parent communication beyond routine handovers is attempted without referring to the class teacher", "good": "Is respectful and professional with students and colleagues, refers parent communication beyond routine handovers to the class teacher, and supports aftercare reliably when rostered", "better": "Builds positive relationships with students that support classroom routines and small group work, and communicates clearly with the teacher and Aftercare Manager", "best": "Is sought out by the class teacher and Aftercare Manager as a dependable, trusted member of the team"}]'::jsonb, '["Safeguarding clearance and background checks current", "Ratios maintained at all times", "Locum teaching of core subjects delivered only from the absent teacher''s plans and as arranged by the Phase Coordinator", "Does not finalise assessment marks or report comments, and does not communicate with parents beyond routine handovers", "PBS incidents and observations reported to the class teacher promptly", "Student and family information handled in line with POPIA", "Signed review documentation on file for every review cycle"]'::jsonb, 20),
  ('subject_head', 'Subject Head', 'Covers the Subject Head roles for Maths, Sciences, Commerce and Humanities, who report to the Deputy Head Academics, hold no direct reports but lead their subject team functionally across Grade 4 to 12, and have their subject standards approved by the Head of Prep School (Grade 4 to 7) and the Head of High School (Grade 8 to 12).', '[{"name": "Curriculum alignment and standard setting", "dnm": "Schemes of work, common assessments or marking standards are missing, inconsistent across grades, or submitted late for approval", "good": "Schemes of work, common assessments and marking standards are drafted for the full Grade 4 to 12 span and submitted for approval on schedule", "better": "Vertical alignment is demonstrated with clear progression between grade bands, and standards are adjusted where moderation shows drift", "best": "The subject can show a coherent, evidenced Grade 4 to 12 progression that the approving Head of phase relies on with minimal amendment"}, {"name": "Assessment moderation", "dnm": "Moderation of subject assessments and bookwork is inconsistent, skipped, or marking standards vary significantly between teachers", "good": "Moderation of assessments and bookwork is completed for the subject team, with marking standards applied consistently", "better": "Moderation samples identify and correct marking inconsistencies before assessments are returned to students", "best": "Moderation evidence shows sustained consistency across the subject team, with no upheld family concern about marking fairness"}, {"name": "IEB SBA and portfolio compliance", "dnm": "IEB SBA or portfolio requirements, including cluster moderation, are missed or incomplete for the subject", "good": "IEB SBA and portfolio compliance, including cluster moderation, is met for every applicable class", "better": "Cluster moderation feedback is used to adjust internal assessment practice ahead of the next submission", "best": "The subject has no cluster moderation finding requiring correction, and its SBA and portfolio practice is used as a reference by the Academic Coordinator"}, {"name": "Cambridge to IEB transition management", "dnm": "The subject''s transition planning from Grade 10 down is unclear, or a Cambridge Grade 11 or 12 cohort is left without adequate subject support", "good": "The subject is transitioning from Cambridge to IEB from Grade 10 down, with Cambridge cohorts in Grade 11 and 12 protected to the end of 2028", "better": "Teachers across the subject team are prepared and supported for both curricula during the overlap period, with no disruption to either cohort", "best": "The subject''s transition is cited as a model of managing dual curricula without disadvantaging either cohort"}, {"name": "Teacher coaching and CPD", "dnm": "Subject team meetings or subject-specific CPD do not happen regularly, or teachers receive no coaching or appraisal evidence", "good": "Subject team meetings and subject-specific CPD run regularly, and teachers are coached with evidence provided for appraisal", "better": "Coaching is targeted to individual teacher development needs identified through observation or moderation", "best": "Teacher capability across the subject team shows measurable improvement, with teachers seeking this Subject Head''s guidance proactively"}, {"name": "Progress monitoring", "dnm": "At-risk students or classes are not identified or flagged in a timely way", "good": "Students and classes at risk are identified and flagged promptly to the Deputy Head Academics or Head of Prep School, and subject reporting to families is accurate", "better": "Flags are accompanied by a clear recommendation or intervention, not only a data point", "best": "Early flagging from this subject demonstrably contributes to successful remediation outcomes"}]'::jsonb, '["Every safeguarding concern is escalated immediately to the phase safeguarding lead, or directly to the Executive Head if the lead is implicated or unavailable.", "Behaviour patterns and incidents in the subject are recorded on the PBS system accurately and within 24 hours, with restorative practice as the default response, and flagged to the Grade Coordinator where relevant.", "Student assessment and progress data in the subject is handled in line with POPIA.", "Schemes of work, common assessments and marking standards are submitted for phase Head approval within the agreed timeline every cycle.", "IEB SBA and portfolio submissions, including cluster moderation, meet all deadlines with no missed submission.", "Cambridge Grade 11 and 12 cohorts in the subject are protected to the end of 2028, with no candidate disadvantaged by the transition to IEB from Grade 10 down.", "At-risk students or classes are flagged to the Deputy Head Academics or Head of Prep School within the reporting cycle in which they are identified.", "Moderation records for the subject are retained and available for audit."]'::jsonb, 21),
  ('operations_lead', 'Operations Lead', 'Covers facilities, procurement, health and safety, and operational service delivery across the whole school. Each dimension is assessed independently rather than averaged into a single score.', '[{"name": "Facilities and infrastructure management", "dnm": "Maintenance requests or facilities issues go unresolved beyond agreed timelines without documented reason; safety-critical issues are not prioritised", "good": "Facilities and maintenance requests are actioned within agreed timelines; safety-critical issues are prioritised and resolved first", "better": "Runs a preventive maintenance schedule that measurably reduces reactive or emergency repairs across the term", "best": "Infrastructure planning reflects a tracked, multi-term capital plan; can evidence cost or downtime savings attributable to decisions made"}, {"name": "Procurement and vendor management", "dnm": "Procurement does not follow the school''s approval process, or vendor performance issues are not addressed", "good": "Procurement follows the school''s approval process; vendor performance is monitored and issues are raised with vendors directly", "better": "Negotiates vendor terms proactively; can evidence cost savings or service improvements from vendor management this cycle", "best": "Has built a vendor panel or procurement approach that other departments or ThriveEd schools reference"}, {"name": "Health, safety and risk management", "dnm": "Safety inspections, risk assessments or incident reports are missed, late or incomplete", "good": "Safety inspections and risk assessments are completed on schedule; incidents are logged and reported per protocol", "better": "Identifies and closes safety risks proactively, ahead of a scheduled inspection surfacing them", "best": "The school''s safety record and audit readiness under this role''s oversight is a model other departments are directed to"}, {"name": "Staff leadership within Operations", "dnm": "Operations staff''s goal-setting, reviews or conduct concerns are not actioned on the required timeline", "good": "Operations staff have goals set and reviews completed on schedule; conduct or performance concerns are documented and actioned per policy", "better": "Coaches operations staff proactively; cross-trains the team so service delivery does not depend on one individual", "best": "Can evidence a measurable improvement in operations team capability or retention attributable to this leadership"}, {"name": "Service delivery to academic staff and students", "dnm": "Repeated, avoidable service failures affect teaching time or student safety, for example classrooms not ready or safety equipment unavailable", "good": "Operational services, facilities readiness, transport, security, cleaning, reliably support the school day without disrupting teaching time", "better": "Proactively communicates planned disruptions to affected staff ahead of time; gathers and acts on feedback from academic staff about service quality", "best": "Is named by Heads of Phase as a trusted operational partner who anticipates their needs"}, {"name": "Budget and resource management", "dnm": "Operational spending is not tracked against budget, or resourcing decisions are made without reference to the approved budget", "good": "Manages the operations budget within approved limits; spend is tracked and reported accurately", "better": "Identifies cost efficiencies without compromising safety or service quality", "best": "Operational spend decisions can be shown to have delivered measurable savings or service improvement relative to budget"}]'::jsonb, '["Safety-critical maintenance or risk issues are escalated to the Executive Head immediately, never held pending informal resolution", "All required safety inspections, certifications and risk assessments are current at all times", "Procurement follows the school''s approved financial policy without exception", "Operations budget and spend reporting are submitted to the Executive Head and Finance by published deadlines", "Serious incidents, safety, security or property, are reported per protocol on the day they occur", "Signed goal-setting and review documentation is on file for every direct report, every cycle"]'::jsonb, 22),
  ('sports_coach', 'Sports Coach / PE Teacher', 'Covers staff who deliver PE lessons and/or coach extramural sport, across all phases. Where a role is coaching-only or PE-only, the manager applies whichever dimensions are relevant and marks the rest not applicable.', '[{"name": "Coaching and instructional delivery", "dnm": "Training sessions or PE lessons are frequently unplanned, run significantly over or under time, or are not matched to the age and skill level of the group.", "good": "Training sessions and PE lessons are planned, run to time and match the age and skill level of the group.", "better": "Sessions build progressively across the term toward a clear skill or fitness target; individual technique feedback is given, not only group instruction.", "best": "Session plans reflect a tracked, term-long athlete development pathway; other coaches or PE staff seek this person out for coaching guidance."}, {"name": "Athlete and student development", "dnm": "Safety in participation, or fairness in selection and game time, is inconsistent.", "good": "Students and athletes participate safely and are treated fairly in selection and game time.", "better": "Individual progress is tracked across the season, with specific, actionable feedback given to each student or athlete.", "best": "Can evidence measurable improvement in fitness, skill or team performance over the season, including for students who started furthest behind."}, {"name": "Safety, supervision and behaviour management (PBS-aligned)", "dnm": "Supervision ratios, equipment checks or safety protocols are inconsistently followed, or incidents are logged late, inaccurately or not at all.", "good": "Supervision ratios, equipment checks and safety protocols are followed at every training session and fixture; incidents are logged accurately and promptly.", "better": "Uses restorative conversations as the first response to behaviour incidents; proactively reinforces positive behaviour consistent with PBS benchmarks.", "best": "Is a visible model of safe, PBS-aligned coaching practice that newer staff or interns are placed with to observe."}, {"name": "Relationships and communication", "dnm": "Selection decisions, fixture changes or results are communicated late, unclearly or not communicated at all.", "good": "Selection decisions, fixture changes and results are communicated to parents and students clearly and on time.", "better": "Communicates proactively with parents about both concerns and progress, not only when a selection dispute arises.", "best": "Is trusted by parents, students and colleagues to handle sensitive selection or team conversations well."}, {"name": "Professional growth and reflection", "dnm": "Required CPD or coaching accreditation renewals are not completed.", "good": "Completes required CPD and coaching accreditation renewals.", "better": "Applies CPD or coaching development visibly in practice; seeks feedback from peers or the Head of Sports.", "best": "Leads or co-leads a coaching CPD session or mentoring arrangement for colleagues."}, {"name": "Contribution to school life", "dnm": "Rostered fixtures, trainings or events are missed or consistently under-delivered.", "good": "Meets minimum expectations for fixtures, trainings and events as rostered.", "better": "Takes ownership of a specific team, event or Pathways-aligned sporting initiative for the term.", "best": "The initiative led has a visible, evidenced impact on participation or team performance beyond the immediate squad."}]'::jsonb, '["Required coaching accreditation, first aid certification and background and safeguarding checks are current at all times", "Present and ready at the start of every rostered training session, PE lesson and fixture; absences are reported per school protocol before the session", "Safety equipment and playing surfaces are checked before use, with any concern reported before the session proceeds", "Injuries are logged and reported per school protocol on the day they occur, with parents notified the same day for anything beyond minor first aid", "All behaviour incidents are logged on the PBS system within 24 hours", "Selection decisions are communicated to students and parents by the published deadline, not left until immediately before a fixture", "Safeguarding concerns are escalated immediately per the school''s child protection policy and never held back pending informal resolution", "Student and family information is handled in line with POPIA at all times", "Signed goal-setting and review documentation is on file for every cycle"]'::jsonb, 23)
